function initTabs(){const e=document.querySelectorAll(".tab-btn"),t=document.querySelectorAll(".tab-content");e.forEach(r=>{r.addEventListener("click",()=>{e.forEach(e=>{e.classList.remove("active"),e.setAttribute("aria-selected","false")}),t.forEach(e=>e.classList.remove("active")),r.classList.add("active"),r.setAttribute("aria-selected","true"),document.getElementById(r.getAttribute("data-tab")).classList.add("active")})})}function initQuiz(){const e=document.getElementById("rajapur-quiz-form"),t=document.getElementById("quiz-result"),r={q1:"2",q2:"2"};e&&e.addEventListener("submit",i=>{i.preventDefault();let o=0;const n=new FormData(e);for(let[e,t]of n.entries())r[e]===t&&o++;const a=Object.keys(r).length;t.textContent=o===a?`🎉 Perfect! ${o}/${a}`:`You scored ${o}/${a}`,t.style.color=o===a?"green":"orange"})}function initGalleryModal(){const e=document.getElementById("gallery-modal"),t=document.getElementById("modal-title"),r=document.getElementById("modal-desc"),i=document.querySelector(".modal-close");document.querySelectorAll(".gallery-item").forEach(i=>{i.addEventListener("click",()=>{t.textContent=i.getAttribute("data-title"),r.textContent=i.getAttribute("data-desc"),e.classList.add("active")})}),i&&i.addEventListener("click",()=>e.classList.remove("active")),window.addEventListener("click",t=>{t.target===e&&e.classList.remove("active")})}function initScrollTop(){const e=document.getElementById("btn-scroll-top");e&&(window.addEventListener("scroll",()=>e.classList.toggle("visible",window.scrollY>300)),e.addEventListener("click",()=>window.scrollTo({top:0,behavior:"smooth"})))}function registerJourneyItems(){window.Journey&&window.Journey.registerSearchItems&&window.Journey.registerSearchItems("rajapur-port-explorer/index.html",[{id:"rajapur-overview",title:"Rajapur Historical Background",description:"The strategic Maratha coastal hub.",link:"rajapur-port-explorer/index.html#overview"},{id:"rajapur-factory",title:"British Factory",description:"Early East India Company trading post.",link:"rajapur-port-explorer/index.html#trade"}])}document.addEventListener("DOMContentLoaded",()=>{initTabs(),initQuiz(),initGalleryModal(),initScrollTop(),registerJourneyItems()});